name: Set Pay attention label for ignored issues
on:
  schedule:
    - cron: '0 10 * * 1-5'

jobs:
  set-label-for-issues:
    runs-on: ubuntu-latest
    steps:
      - name: Set Pay attention label for ignored issues
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.DEVTOOLS_GITHUB_TOKEN }}
          script: |
            const issuesList = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
            })
            if (issuesList.data && issuesList.status === 200) {
              for (const issue of issuesList.data) {
                const createdDaysDelta = (new Date() - new Date(issue.created_at)) / (1000 * 60 * 60 * 24);

                if (!issue.labels.length && (
                  (!issue.pull_request && createdDaysDelta > 2) || (issue.pull_request && createdDaysDelta > 7)
                )) {
                  await github.rest.issues.addLabels({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: issue.number,
                    labels: ['pay attention']
                  });
                }
              }
            }

import { ApiEndpoint } from 'src/types'

const API_URL = 'https://shop-boilerplate-backend.vercel.app'

interface Arguments {
  endpoint: ApiEndpoint
  params?: Record<string, string>
  requestOptions?: RequestInit
}

/**
 * Обертка над http запросом, чтобы обеспечить независимость от используемых библиотек 
 * @param endpoint - api endpoint
 * @param params - query параметры запроса в виде объекта
 * @param requestOptions - настройки запроса: method, headers, cashe
 * @returns ответ сервера
 * @example 
  // get запрос
  makeRequest(endpoint: 'productInfo', params: {id: '2'})
  // post запрос
  makeRequest('postProduct', requestOptions: JSON.stringify({method: 'post', body: {id: 2}}))
 */
export const makeRequest = async <T = never>({
  params,
  endpoint,
  requestOptions,
}: Arguments): Promise<T> => {
  const url = new URL(API_URL + '/' + endpoint)
  url.search = new URLSearchParams(params).toString()

  return (await fetch(url, requestOptions)).json() as T
}

import { ApiEndpoint, ProductFilter, ProductPreview } from 'src/types'
import { makeRequest } from 'src/api/makeRequest'

export interface GetProductsRequest {
  /** Порядковый номер первого возвращаемого товара в списке */
  start: number

  /** Порядковый номер последнего возвращаемого товара в списке */
  end: number

  /** Фильтры пользователя */
  filters: ProductFilter
}

export interface GetProductsResponse {
  /** Отфильтрованные продукты с порядковыми номерами от _start до _end */
  products: ProductPreview[]

  /** Общее количество отфильтрованных продуктов */
  filteredProductCount: number
}

/** Получение списка товаров в соответствии с фильтрами */
export const getFilteredProducts = async ({
  end,
  start,
  filters,
}: GetProductsRequest): Promise<GetProductsResponse> => {
  return await makeRequest<GetProductsResponse>({
    endpoint: ApiEndpoint.FilteredProducts,
    params: {
      end: end.toString(),
      start: start.toString(),
      filters: JSON.stringify(filters),
    },
  })
}

import { ApiEndpoint, Product } from 'src/types'
import { makeRequest } from 'src/api/makeRequest'

export interface GetProductInfoRequest {
  productId: number
}

/** Получение информации по конкретному товару */
export const getProductInfo = async ({
  productId,
}: GetProductInfoRequest): Promise<Product> => {
  return await makeRequest<Product>({
    endpoint: ApiEndpoint.ProductInfo,
    params: {
      id: productId.toString(),
    },
  })
}

import { ApiEndpoint, Category } from 'src/types'
